/**
 * The fixed Android resources: the adaptive-icon pair, the launcher background colour, and
 * the copies of the artefacts `scripts/build-brand-mark.mjs` owns.
 *
 * The splash vector is not re-derived here. It is generated by the legacy mark script from the
 * same canonical SVG; duplicating that geometry would create a second source for the one thing
 * the splash has to get right. Instead the copy is checked against the ink this pipeline
 * measured, so a stale vector is a failure rather than a surprise on a phone.
 */
import { copyFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { basename, dirname, join } from "node:path";

import { LEGACY, OUT } from "../core/paths.mjs";
import { generated, ok, skip } from "../core/report.mjs";

const XML_HEADER = '<?xml version="1.0" encoding="utf-8"?>';

/**
 * The legacy script measures the silhouette at 768px, this pipeline at 1024px, so a sub-pixel
 * difference in the ink centre is expected. The check is "agrees within a pixel of sampling",
 * not "matches byte for byte".
 */
const TRANSLATE_TOLERANCE = 1.5;

export const adaptiveIconXml = () => `${XML_HEADER}
<!-- Generated by scripts/brand/cli.mjs. Do not edit by hand. -->
<adaptive-icon xmlns:android="http://schemas.android.com/apk/res/android">
    <background android:drawable="@color/ic_launcher_background" />
    <foreground android:drawable="@mipmap/ic_launcher_foreground" />
    <monochrome android:drawable="@mipmap/ic_launcher_monochrome" />
</adaptive-icon>
`;

export const launcherBackgroundXml = (hex) => `${XML_HEADER}
<!--
  Generated by scripts/brand/cli.mjs from packages/tokens/tokens.css.
  One colour, not a light/dark pair: the launcher paints the icon on its own surface, so a
  night value would only change the plate the mark sits on between two adjacent icons.
-->
<resources>
    <color name="ic_launcher_background">${hex.toUpperCase()}</color>
</resources>
`;

const write = (path, data) => {
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, data);
  return path;
};

export const emitFixedResources = (tokens) => {
  const anydpi = join(OUT.android, "mipmap-anydpi-v26");
  const files = [
    write(join(anydpi, "ic_launcher.xml"), adaptiveIconXml()),
    write(join(anydpi, "ic_launcher_round.xml"), adaptiveIconXml()),
    write(
      join(OUT.android, "values", "ic_launcher_background.xml"),
      launcherBackgroundXml(tokens.colors.light.background)
    )
  ];
  generated("android adaptive xml", files.length, "background, foreground, monochrome");
  return files;
};

export const emitCopies = () => {
  const copies = [
    [LEGACY.splashVector, join(OUT.android, "drawable", "ic_splash_mark.xml")],
    [LEGACY.mobileSvg, join(OUT.android, "mobile", "brand-mark.svg")],
    [LEGACY.mobilePaths, join(OUT.android, "mobile", "brand-mark-paths.ts")]
  ];

  const files = [];
  for (const [from, to] of copies) {
    if (!existsSync(from)) {
      skip(`android copy ${basename(from)}`, "the committed artefact is absent");
      continue;
    }
    mkdirSync(dirname(to), { recursive: true });
    copyFileSync(from, to);
    files.push(to);
  }
  generated("android copies", files.length, "splash vector and the mobile mark");
  return files;
};

export const checkSplashVector = (tokens) => {
  const splash = tokens.icon.android.splash;
  const side = Math.ceil((tokens.mark.ink.radius * splash.canvasDp) / splash.targetRadiusDp);
  const expected = {
    x: side / 2 - tokens.mark.ink.centre.x,
    y: side / 2 - tokens.mark.ink.centre.y
  };

  const file = join(OUT.android, "drawable", "ic_splash_mark.xml");
  if (!existsSync(file)) {
    skip("android splash vector", "the copied vector is absent, so there is nothing to compare");
    return;
  }

  const xml = readFileSync(file, "utf8");
  const viewport = Number(/android:viewportWidth="([\d.]+)"/.exec(xml)?.[1]);
  const translate = {
    x: Number(/android:translateX="(-?[\d.]+)"/.exec(xml)?.[1]),
    y: Number(/android:translateY="(-?[\d.]+)"/.exec(xml)?.[1])
  };
  const fills = [...xml.matchAll(/android:fillColor="([^"]+)"/g)].map((match) => match[1]);

  if (viewport !== side) {
    throw new Error(`the splash viewport is ${viewport}, expected ${side} from the measured ink`);
  }
  if (
    Math.abs(translate.x - expected.x) > TRANSLATE_TOLERANCE ||
    Math.abs(translate.y - expected.y) > TRANSLATE_TOLERANCE
  ) {
    throw new Error(
      `the splash is centred at (${translate.x}, ${translate.y}); the measured ink wants (${expected.x.toFixed(2)}, ${expected.y.toFixed(2)})`
    );
  }
  if (fills.length === 0 || fills.some((fill) => fill !== "@color/splash_mark")) {
    throw new Error(`the splash mark's fill is not a themed resource: ${fills.join(", ")}`);
  }
  ok("android splash vector", `${side}u viewport, translate (${translate.x}, ${translate.y})`);
};
